/**
 * List ordering helpers.
 *
 * `reorderVisible` only swaps the ids that are on screen. Hidden rows keep
 * their slots. That behavior is adapted from the MIT-licensed admin panel by
 * Maniruzzaman Jubayer (Copyright (c) 2026). See NOTICE.
 */

export function moveItem<T>(list: readonly T[], from: number, to: number): T[] {
  if (
    from === to ||
    from < 0 ||
    to < 0 ||
    from >= list.length ||
    to >= list.length
  ) {
    return [...list]
  }
  const next = list.slice()
  const [item] = next.splice(from, 1)
  if (item === undefined) return [...list]
  next.splice(to, 0, item)
  return next
}

export type MoveDirection = "up" | "down" | "top" | "bottom"

export function destinationIndex(
  index: number,
  count: number,
  target: MoveDirection | number,
): number {
  if (count <= 0) return 0
  if (typeof target === "number") {
    return Math.max(0, Math.min(count - 1, target))
  }
  if (target === "up") return Math.max(0, index - 1)
  if (target === "down") return Math.min(count - 1, index + 1)
  if (target === "top") return 0
  return count - 1
}

/**
 * Reorder `order` by moving `activeId` to the slot of `overId`, but only
 * among `visibleIds`. Ids that are not visible stay where they are.
 */
export function reorderVisible(
  order: readonly string[],
  visibleIds: readonly string[],
  activeId: string,
  overId: string,
): string[] {
  const from = visibleIds.indexOf(activeId)
  const to = visibleIds.indexOf(overId)
  if (from < 0 || to < 0 || from === to) return [...order]
  const nextVisible = moveItem(visibleIds, from, to)
  const slots = new Set(visibleIds)
  let cursor = 0
  return order.map((id) => {
    if (!slots.has(id)) return id
    const next = nextVisible[cursor]
    cursor += 1
    return next ?? id
  })
}

export function reorderRows<T extends { id: string; position: number }>(
  rows: readonly T[],
  ids: readonly string[],
): T[] {
  const byId = new Map(rows.map((row) => [row.id, row]))
  const seen = new Set<string>()
  const next: T[] = []
  for (const id of ids) {
    const row = byId.get(id)
    if (!row || seen.has(id)) continue
    seen.add(id)
    next.push({ ...row, position: next.length })
  }
  for (const row of rows) {
    if (seen.has(row.id)) continue
    next.push({ ...row, position: next.length })
  }
  return next
}

/** Keep the stored position when a form saves an existing row. */
export function keepPosition<T extends { position: number }>(
  current: T | undefined,
  draft: T,
): T {
  if (!current) return draft
  return { ...draft, position: current.position }
}

/** URL slug from a human title. Accents are stripped. */
export function slugify(value: string): string {
  return value
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
}

/**
 * `slugify(base)`, then `-2`, `-3`, … until the slug is unused.
 * `ignore` is a slug that does not count as taken (the row being edited).
 */
export function uniqueSlug(
  base: string,
  existing: Iterable<string>,
  ignore?: string,
): string {
  const slug = slugify(base) || "item"
  const taken = new Set(existing)
  if (ignore) taken.delete(ignore)
  if (!taken.has(slug)) return slug
  let n = 2
  while (taken.has(`${slug}-${n}`)) n += 1
  return `${slug}-${n}`
}

export function createId(): string {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return crypto.randomUUID()
  }
  return `id-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`
}

export type CsvColumn = {
  key: string
  header: string
}

export function escapeCsvCell(value: unknown): string {
  if (value == null) return ""
  const text = String(value)
  if (/[",\n\r]/.test(text)) return `"${text.replace(/"/g, '""')}"`
  return text
}

export function toCsv(
  rows: readonly Record<string, unknown>[],
  columns: readonly CsvColumn[],
): string {
  const head = columns.map((column) => escapeCsvCell(column.header)).join(",")
  const body = rows
    .map((row) => columns.map((column) => escapeCsvCell(row[column.key])).join(","))
    .join("\n")
  return body ? `${head}\n${body}` : head
}

export function downloadCsv(filename: string, csv: string) {
  if (typeof document === "undefined") return
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" })
  const url = URL.createObjectURL(blob)
  const link = document.createElement("a")
  link.href = url
  link.download = filename.endsWith(".csv") ? filename : `${filename}.csv`
  link.click()
  URL.revokeObjectURL(url)
}

export function formatNumber(value: number, locale = "es"): string {
  return new Intl.NumberFormat(locale).format(value)
}

/** Relative change. `null` when the previous value is 0 and the current is not. */
export function percentDelta(current: number, previous: number): number | null {
  if (previous === 0) return current === 0 ? 0 : null
  return (current - previous) / Math.abs(previous)
}

export function formatPercentDelta(delta: number | null, locale = "es"): string {
  if (delta == null) return "—"
  const pct = Math.round(delta * 100)
  const formatted = new Intl.NumberFormat(locale, {
    signDisplay: "exceptZero",
  }).format(pct)
  return `${formatted}%`
}

export function formatBytes(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes < 0) return "0 B"
  if (bytes < 1024) return `${Math.round(bytes)} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

export function formatWhen(ts: number | null, locale = "es", timeZone?: string): string {
  if (ts == null) return "—"
  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone,
  }).format(ts)
}

/** shadcn chart tokens. Hosts define --chart-1 … --chart-5. */
export const CHART_TONES = [1, 2, 3, 4, 5] as const

export type ChartTone = (typeof CHART_TONES)[number]

export function chartVar(tone: ChartTone = 1): string {
  return `var(--chart-${tone})`
}

export function chartBgClass(tone: ChartTone = 1): string {
  switch (tone) {
    case 1:
      return "bg-chart-1"
    case 2:
      return "bg-chart-2"
    case 3:
      return "bg-chart-3"
    case 4:
      return "bg-chart-4"
    case 5:
      return "bg-chart-5"
  }
}

export function chartFillClass(tone: ChartTone = 1): string {
  switch (tone) {
    case 1:
      return "fill-chart-1"
    case 2:
      return "fill-chart-2"
    case 3:
      return "fill-chart-3"
    case 4:
      return "fill-chart-4"
    case 5:
      return "fill-chart-5"
  }
}

export const RANGE_OPTIONS = [
  { key: "today", label: "Today" },
  { key: "7d", label: "Last 7 days" },
  { key: "30d", label: "Last 30 days" },
  { key: "90d", label: "Last 90 days" },
  { key: "12m", label: "Last 12 months" },
] as const

export type RangeKey = (typeof RANGE_OPTIONS)[number]["key"]

export type ResolvedRange = {
  key: RangeKey
  label: string
  from: number
  to: number
  prevFrom: number
  prevTo: number
  bucket: "hour" | "day" | "month"
}

const DAY = 86_400_000

export function isRangeKey(value: string): value is RangeKey {
  return RANGE_OPTIONS.some((option) => option.key === value)
}

/** Offset of `timeZone` at `ts`, in ms. UTC is 0. */
export function timeZoneOffsetMs(timeZone: string, ts: number): number {
  const formatted = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(new Date(ts))
  const parts = Object.fromEntries(formatted.map((part) => [part.type, part.value]))
  const asUtc = Date.UTC(
    Number(parts.year),
    Number(parts.month) - 1,
    Number(parts.day),
    Number(parts.hour) % 24,
    Number(parts.minute),
    Number(parts.second),
  )
  return asUtc - ts
}

export function startOfZonedDay(ts: number, timeZone = "UTC"): number {
  const offset = timeZoneOffsetMs(timeZone, ts)
  const local = ts + offset
  const midnightLocal = Math.floor(local / DAY) * DAY
  const guess = midnightLocal - timeZoneOffsetMs(timeZone, midnightLocal - offset)
  const check = timeZoneOffsetMs(timeZone, guess)
  return midnightLocal - check
}

export function resolveRange(
  key: RangeKey,
  now = Date.now(),
  timeZone = "UTC",
): ResolvedRange {
  const option = RANGE_OPTIONS.find((item) => item.key === key) ?? RANGE_OPTIONS[1]
  const today = startOfZonedDay(now, timeZone)
  let from = today
  let bucket: ResolvedRange["bucket"] = "day"
  let span = DAY

  if (key === "today") {
    from = today
    bucket = "hour"
    span = DAY
  } else if (key === "12m") {
    const offset = timeZoneOffsetMs(timeZone, today)
    const local = new Date(today + offset)
    const start = Date.UTC(local.getUTCFullYear(), local.getUTCMonth() - 11, 1)
    from = start - timeZoneOffsetMs(timeZone, start - offset)
    bucket = "month"
    span = now - from
  } else {
    const days = key === "7d" ? 7 : key === "30d" ? 30 : 90
    from = today - (days - 1) * DAY
    span = days * DAY
    bucket = "day"
  }

  return {
    key: option.key,
    label: option.label,
    from,
    to: now,
    prevFrom: from - span,
    prevTo: now - span,
    bucket,
  }
}

/** Inclusive window. */
export function inRange(ts: number, from: number, to: number): boolean {
  return ts >= from && ts <= to
}

export function filterByRange<T>(
  rows: readonly T[],
  getTime: (row: T) => number | null,
  from: number,
  to: number,
): T[] {
  return rows.filter((row) => {
    const ts = getTime(row)
    return ts != null && inRange(ts, from, to)
  })
}

export type DatePreset = {
  key: string
  label: string
}

export const CALL_PRESETS: DatePreset[] = [
  { key: "any", label: "Any time" },
  { key: "today", label: "Today" },
  { key: "tomorrow", label: "Tomorrow" },
  { key: "next7", label: "Next 7 days" },
  { key: "next30", label: "Next 30 days" },
  { key: "last7", label: "Last 7 days" },
  { key: "last30", label: "Last 30 days" },
]

/** `[from, to)` for a named preset, or null when the preset does not filter. */
export function presetBounds(
  preset: string,
  now = Date.now(),
  timeZone = "UTC",
): [number, number] | null {
  const today = startOfZonedDay(now, timeZone)
  switch (preset) {
    case "today":
      return [today, today + DAY]
    case "tomorrow":
      return [today + DAY, today + 2 * DAY]
    case "next7":
      return [now, now + 7 * DAY]
    case "next30":
      return [now, now + 30 * DAY]
    case "last7":
      return [now - 7 * DAY, now]
    case "last30":
      return [now - 30 * DAY, now]
    case "last90":
      return [now - 90 * DAY, now]
    default:
      return null
  }
}

import type {
  AnalyticsClick,
  AnalyticsSnapshot,
  AnalyticsView,
  DailyMetric,
  LabeledValue,
} from "@/registry/retana/lib/admin-types"
import { inRange } from "@/registry/retana/lib/date-range"

const DAY = 86_400_000

function dateKey(ts: number): string {
  return new Date(ts).toISOString().slice(0, 10)
}

function hostOf(referrer: string | null): string {
  if (!referrer) return "Directo"
  try {
    const url = referrer.includes("://") ? new URL(referrer) : new URL(`https://${referrer}`)
    return url.host.replace(/^www\./, "") || "Directo"
  } catch {
    return referrer
  }
}

function bump(map: Map<string, number>, key: string, by = 1) {
  map.set(key, (map.get(key) ?? 0) + by)
}

function top(map: Map<string, number>, limit: number): LabeledValue[] {
  return [...map.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, limit)
    .map(([label, value]) => ({ label, value }))
}

/**
 * Turn raw page views and clicks into the snapshot the chart pieces render.
 * The window is inclusive. Empty days inside the window stay in `daily`.
 */
export function summarizeAnalytics(
  views: readonly AnalyticsView[],
  clicks: readonly AnalyticsClick[],
  from: number,
  to: number,
): AnalyticsSnapshot {
  const inWindow = views.filter((view) => inRange(view.ts, from, to))
  const clicksInWindow = clicks.filter((click) => inRange(click.ts, from, to))

  const visitorsByDay = new Map<string, Set<string>>()
  const viewsByDay = new Map<string, number>()
  const clicksByDay = new Map<string, number>()
  const sources = new Map<string, number>()
  const sessions = new Set<string>()
  const pricingSessions = new Set<string>()
  const clickSessions = new Set<string>()
  const heat: number[][] = Array.from({ length: 7 }, () => Array.from({ length: 24 }, () => 0))
  const scroll = { s25: 0, s50: 0, s75: 0, s90: 0, s100: 0 }

  for (const view of inWindow) {
    const key = dateKey(view.ts)
    const set = visitorsByDay.get(key) ?? new Set<string>()
    set.add(view.visitor)
    visitorsByDay.set(key, set)
    bump(viewsByDay, key)
    bump(sources, hostOf(view.referrer))
    sessions.add(view.session)
    if (view.path.includes("precio") || view.path.includes("pricing") || view.path.includes("planes")) {
      pricingSessions.add(view.session)
    }
    const date = new Date(view.ts)
    const mondayIndex = (date.getUTCDay() + 6) % 7
    const hour = date.getUTCHours()
    const row = heat[mondayIndex]
    if (row) row[hour] = (row[hour] ?? 0) + 1
    if (view.scrollPct >= 25) scroll.s25 += 1
    if (view.scrollPct >= 50) scroll.s50 += 1
    if (view.scrollPct >= 75) scroll.s75 += 1
    if (view.scrollPct >= 90) scroll.s90 += 1
    if (view.scrollPct >= 100) scroll.s100 += 1
  }

  for (const click of clicksInWindow) {
    bump(clicksByDay, dateKey(click.ts))
    clickSessions.add(click.session)
  }

  const daily: DailyMetric[] = []
  const start = Date.parse(`${dateKey(from)}T00:00:00.000Z`)
  const end = Date.parse(`${dateKey(to)}T00:00:00.000Z`)
  for (let ts = start; ts <= end; ts += DAY) {
    const key = dateKey(ts)
    daily.push({
      date: key,
      visitors: visitorsByDay.get(key)?.size ?? 0,
      views: viewsByDay.get(key) ?? 0,
      clicks: clicksByDay.get(key) ?? 0,
    })
  }

  const total = inWindow.length || 1
  const scrollBars: LabeledValue[] = [
    { label: "25%", value: scroll.s25 / total },
    { label: "50%", value: scroll.s50 / total },
    { label: "75%", value: scroll.s75 / total },
    { label: "90%", value: scroll.s90 / total },
    { label: "100%", value: scroll.s100 / total },
  ]

  return {
    daily,
    sources: top(sources, 6),
    funnel: [
      { label: "Sesiones", value: sessions.size },
      { label: "Vieron precios", value: pricingSessions.size },
      { label: "Hicieron clic", value: clickSessions.size },
    ],
    scroll: scrollBars,
    heat,
  }
}

export function sumDaily(daily: readonly DailyMetric[]) {
  return daily.reduce(
    (acc, day) => ({
      visitors: acc.visitors + day.visitors,
      views: acc.views + day.views,
      clicks: acc.clicks + day.clicks,
    }),
    { visitors: 0, views: 0, clicks: 0 },
  )
}

"use client"

import * as React from "react"

import { reorderVisible } from "@/registry/retana/lib/reorder"

export type ListNotify = {
  success: (message: string) => void
  error: (message: string) => void
}

type UseOptimisticListOptions<T extends { id: string }> = {
  items: readonly T[]
  onReorder: (ids: readonly string[]) => Promise<void> | void
  notify?: ListNotify
  savedMessage?: string
  errorMessage?: string
}

/**
 * Shows the next order immediately. If `onReorder` rejects, the previous
 * order is restored and `notify.error` runs.
 */
export function useOptimisticList<T extends { id: string }>({
  items,
  onReorder,
  notify,
  savedMessage = "Order saved",
  errorMessage = "Could not save the order",
}: UseOptimisticListOptions<T>) {
  const idsKey = items.map((item) => item.id).join("\0")
  const [order, setOrder] = React.useState(() => items.map((item) => item.id))
  const [seen, setSeen] = React.useState(idsKey)
  const [pending, setPending] = React.useState(false)

  if (seen !== idsKey) {
    setSeen(idsKey)
    setOrder(items.map((item) => item.id))
  }

  const byId = React.useMemo(() => new Map(items.map((item) => [item.id, item])), [items])
  const ordered = order.map((id) => byId.get(id)).filter((item): item is T => item != null)

  const commit = React.useCallback(
    async (next: readonly string[]) => {
      const before = order
      if (before.join("\0") === next.join("\0")) return
      setOrder([...next])
      setPending(true)
      try {
        await onReorder(next)
        notify?.success(savedMessage)
      } catch (error) {
        setOrder(before)
        const message = error instanceof Error && error.message ? error.message : errorMessage
        notify?.error(message)
      } finally {
        setPending(false)
      }
    },
    [errorMessage, notify, onReorder, order, savedMessage],
  )

  const moveVisible = React.useCallback(
    (visibleIds: readonly string[], activeId: string, overId: string) => {
      const next = reorderVisible(order, visibleIds, activeId, overId)
      void commit(next)
    },
    [commit, order],
  )

  return { items: ordered, order, pending, commit, moveVisible }
}

"use client"

import * as React from "react"

/**
 * Warn before the tab closes while `dirty` is true.
 * Returns the same flag so a sticky bar can read it.
 */
export function useUnsavedChanges(dirty: boolean, message = "You have unsaved changes.") {
  React.useEffect(() => {
    if (!dirty || typeof window === "undefined") return
    const onLeave = (event: BeforeUnloadEvent) => {
      event.preventDefault()
      event.returnValue = message
    }
    window.addEventListener("beforeunload", onLeave)
    return () => window.removeEventListener("beforeunload", onLeave)
  }, [dirty, message])

  return dirty
}

"use client"

import * as React from "react"

import {
  RANGE_OPTIONS,
  resolveRange,
  type RangeKey,
  type ResolvedRange,
} from "@/registry/retana/lib/date-range"

export function useDateRange(initial: RangeKey = "7d", timeZone = "UTC") {
  const [key, setKeyState] = React.useState<RangeKey>(initial)
  const [now, setNow] = React.useState(() => Date.now())

  const range: ResolvedRange = React.useMemo(
    () => resolveRange(key, now, timeZone),
    [key, now, timeZone],
  )

  const setKey = React.useCallback((next: RangeKey) => {
    setNow(Date.now())
    setKeyState(next)
  }, [])

  return { key, setKey, range, options: RANGE_OPTIONS, now }
}

